import java.util.*;

public class Main {
    static long[] onesArray = new long[20];
    static long[] powerArray = new long[20];
    static int minMovesRequired = -1;

    static void initialize() {
        powerArray[0] = 1;
        for (int i = 1; i <= 17; i++) {
            powerArray[i] = powerArray[i - 1] * 10;
        }

        onesArray[0] = 0;
        for (int i = 1; i <= 17; i++) {
            onesArray[i] = onesArray[i - 1] * 10 + 1;
        }
    }

    static int countDigits(long num) {
        int count = 0;
        do {
            count++;
            num /= 10;
        } while (num != 0);
        return count;
    }

    static void searchMin(int digitPos, long val, int steps) {
        if (minMovesRequired != -1 && steps >= minMovesRequired)
            return;
        if (val == 0 || digitPos == 0) {
            if (minMovesRequired == -1 || steps < minMovesRequired)
                minMovesRequired = steps;
            return;
        }
        if (val < 0)
            val = -val;

        long tempVal = val;
        int tempSteps = 0;
        while (tempVal >= powerArray[digitPos - 1]) {
            tempVal -= onesArray[digitPos];
            tempSteps += digitPos;
        }
        searchMin(digitPos - 1, tempVal, steps + tempSteps);

        tempVal = onesArray[digitPos + 1] - val;
        tempSteps = 0;
        while (tempVal >= powerArray[digitPos - 1]) {
            tempVal -= onesArray[digitPos];
            tempSteps += digitPos;
        }
        searchMin(digitPos - 1, tempVal, steps + digitPos + 1 + tempSteps);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        initialize();

        long inputNum = sc.nextLong();
        minMovesRequired = -1;
        int digitCount = countDigits(inputNum);
        searchMin(digitCount, inputNum, 0);
        System.out.println(minMovesRequired);
        sc.close();
    }
}
